const searchResult = $json;
const norm = $('Extract VT Summary').item.json;

let indicators = [];

if (Array.isArray(searchResult?.data)) {
  indicators = searchResult.data;
} else if (Array.isArray(searchResult?.response)) {
  indicators = searchResult.response.flatMap(item =>
    item.Event?.Attribute || item.Attribute || []
  );
} else if (searchResult?.id && searchResult?.value) {
  indicators = [searchResult];
}

const targetValue = norm.src_ip || norm.file_hash || norm.domain || norm.url;

const matches = indicators.filter(indicator =>
  indicator.value === targetValue
);

const firstIndicator = matches[0] || null;

return [{
  json: {
    ...norm,
    soc_app_indicator_found: Boolean(firstIndicator),
    soc_app_indicator_id: firstIndicator?.id || null,
    soc_app_indicator_type: firstIndicator?.type || null,
