const syncResponse = $json;
const norm = $('Extract VT Summary').item.json;

// Response từ POST /api/v1/indicators
const indicator = syncResponse.data || syncResponse;

const indicatorId = indicator.id || '';
const indicatorType = indicator.type || '';
const indicatorValue = indicator.value || '';

return [{
  json: {
    ...norm,

    // Giữ tên field cũ để các node phía sau không bị lỗi
    misp_sync: true,
    misp_event_id: indicatorId,
    misp_event_uuid: indicatorId,

    // Field mới của SOC App
    soc_app_indicator_id: indicatorId,
    soc_app_indicator_type: indicatorType,
    soc_app_indicator_value: indicatorValue,
    soc_app_sync: true,

    src_ip: norm.src_ip,
    event_type: norm.event_type,
    action: 'created'
  }
}];

const report = $json.report || {};

const attributes = report.full?.attributes || {};
const taxonomies = report.summary?.taxonomies || [];
const stats = attributes.last_analysis_stats || {};
const tags = attributes.tags || [];

// =======================
// VirusTotal Statistics
// =======================

const malicious = Number(stats.malicious || 0);
const suspicious = Number(stats.suspicious || 0);
const harmless = Number(stats.harmless || 0);
const undetected = Number(stats.undetected || 0);
const timeout = Number(stats.timeout || 0);

const total =
    malicious +
    suspicious +
    harmless +
    undetected +
    timeout;

const detectionRatio =
    total > 0
        ? `${malicious + suspicious}/${total}`
        : "N/A";

// =======================
// VirusTotal Resolution
// =======================

const resolutions =
    taxonomies.find(t =>
        (t.value || "").toLowerCase().includes("resolution")
    )?.value || "N/A";

// =======================
// Hashes
// =======================

const sha256 =
    attributes.sha256 || "";

const sha1 =
    attributes.sha1 ||
    "N/A";

const md5 =
    attributes.md5 ||
    "N/A";

// =======================
// File Information
// =======================

const fileNames =
    (attributes.names || []).join(", ");

const fileType =
    attributes.type_description ||
    attributes.type_tag ||
    "Unknown";

const fileSize =
    attributes.size || 0;

// =======================
// Threat Classification
// =======================

const threat =
    attributes.popular_threat_classification
        ?.suggested_threat_label ||
    "Unknown";

// =======================
// Last Analysis
// =======================

const lastAnalysis =
    attributes.last_analysis_date
        ? new Date(attributes.last_analysis_date * 1000).toISOString()
        : "Unknown";

// =======================
// Reputation
// =======================

const reputation =
    attributes.reputation ??
    "Unknown";

// =======================
// VirusTotal Link
// =======================

const vtLink =
    attributes.permalink ||
    report.full?.links?.self ||
    "N/A";

// =======================
// IP Information
// =======================

const country =
    attributes.country || "Unknown";

const asOwner =
    attributes.as_owner || "Unknown";

const network =
    attributes.network || "Unknown";

// =======================
// Risk Level
// =======================

let riskLevel = "CLEAN";

if (malicious >= 20)
    riskLevel = "CRITICAL";
else if (malicious >= 10)
    riskLevel = "HIGH";
else if (malicious >= 5)
    riskLevel = "MEDIUM";
else if (malicious > 0)
    riskLevel = "LOW";

// =======================
// Return
// =======================

return [{
    json: {

        ...$('Normalize Payload1').item.json,

        vt_score: detectionRatio,

        vt_detection: detectionRatio,

        vt_total_engines: total,

        vt_malicious_count: malicious,

        vt_suspicious_count: suspicious,

        vt_harmless_count: harmless,

        vt_undetected_count: undetected,

        vt_tags: tags.join(", "),

        vt_sha256: sha256,

        vt_sha1: sha1,

        vt_md5: md5,

        vt_names: fileNames,

        vt_file_type: fileType,

        vt_file_size: fileSize,

        vt_threat: threat,

        vt_last_analysis: lastAnalysis,

        vt_permalink: vtLink,

        vt_reputation: reputation,

        vt_country: country,

        vt_as_owner: asOwner,

        vt_network: network,

        vt_risk_level: riskLevel,

        vt_resolutions: resolutions,

        vt_summary_md:
`🛡 **VirusTotal Analysis**

### Risk Level
• ${riskLevel}

### Detection
• Ratio: ${detectionRatio}

### Reputation
• Malicious : ${malicious}
• Suspicious: ${suspicious}
• Harmless : ${harmless}
• Undetected: ${undetected}

### Threat Classification
• ${threat}

### Tags
• ${tags.length ? tags.join(", ") : "None"}

### Hashes
• SHA256: ${sha256}
• SHA1: ${sha1}
• MD5: ${md5}

### File Information
• Name: ${fileNames || "Unknown"}
• Type: ${fileType}
• Size: ${fileSize} bytes

### Last Analysis
• ${lastAnalysis}

### VirusTotal Report
${vtLink}

### IP Reputation
• Reputation Score: ${reputation}
• Country: ${country}
• ASN Owner: ${asOwner}
• Network: ${network}`
    }
}];

